const touchConversationByRule = `-- name: TouchConversationByRule :exec
UPDATE conversations SET
    last_message_at = CASE WHEN $1::bool THEN greatest(coalesce(last_message_at, $2::timestamptz), $2::timestamptz) ELSE last_message_at END,
    updated_at = $2::timestamptz
WHERE workspace_id = $3 AND id = $4
`

type TouchConversationByRuleParams struct {
	IsMessage   bool
	Now         time.Time
	WorkspaceID uuid.UUID
	ID          uuid.UUID
}

func (q *Queries) TouchConversationByRule(ctx context.Context, arg TouchConversationByRuleParams) error {
	_, err := q.db.Exec(ctx, touchConversationByRule,
		arg.IsMessage,
		arg.Now,
		arg.WorkspaceID,
		arg.ID,
	)
	return err
}

